def canTraverseAllPairs(nums: List[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True

    nums = set(nums)
    if 1 in nums:
        return False

    if len(nums) == 1:
        return True

    nums = sorted(nums, reverse=True)
    i = 0

    while i < n - 1:
        j = i + 1
        while j < n:
            if gcd(nums[i], nums[j]) > 1:
                nums[i] *= nums[j]
                j = n
            else:
                j += 1
        i += 1

    return True

import math
