def findKthSmallest(coins: List[int], k: int) -> int:
    def check(x):
        count = 0
        for mask in range(1 << len(coins)):
            cnt = 0
            c = []
            for i in range(len(coins)):
                if (mask >> i) & 1:
                    cnt += 1
                    c.append(coins[i])
            if cnt == 0:
                continue
            lcm = math.lcm(*c)
            if cnt % 2 == 1:
                count += x // lcm
            else:
                count -= x // lcm
        return count >= k

    l, r = 0, 10**18
    while l + 1 < r:
        m = (l + r) >> 1
        if check(m):
            r = m
        else:
            l = m
    return r

def kthCharacter( k: int, operations: List[int]) -> str:
    i = 0
    count = 0
    while k > 1:
        i = max(i, int(math.ceil(math.log(k, 2))) - 1)
        if k > (1 << i):
            if operations[i] == 1:
                count += 1
            k -= (1 << i)
        i -= 1
    return chr(97 + (count % 26))
